// Give LAN association a normal startup window, then hold/search channels for the direct link.
uint8_t InterComms::getWiFiChannelRequest() const {
  if (!ready() || !_radio.ready() || WiFi.status() == WL_CONNECTED || forceReconnect) return 0;
  bool gateway = WiFi.softAPgetStationNum() > 0;
  for (const auto& peer : _peers) if (peer.live(millis()) && peer.canLead && peer.gatewayScore > 0) gateway = true;
  if (!InterCommsRadio::channelWindow(millis(), _lastLan ? _lastLan : _started, gateway)) return 0;
  return _radioChannel;
}

