// Create one boot epoch and send key after Wi-Fi exists; retry a failed initialization on the next loop.
bool InterComms::initializeSession() {
  if (!_bootReady) {
    if (WiFi.getMode() == WIFI_MODE_NULL) return false;
    esp_fill_random(_boot, 16);
    if (!deriveKey(_id, _boot, _sendKey)) return false;
    _bootReady = true;
    _started = millis();
    _commandId = esp_random();
  }
  return true;
}

// Keep transport, cryptography, settings, and OTA work serialized on the firmware main loop.
// Run admission and election before lighting synchronization, then service bounded update work.
void InterComms::loop() {
  if (!provisioned() || !_idValid || !initializeSession()) return;

  bool connected = WiFi.status() == WL_CONNECTED;
  serviceNetwork(connected);

  uint32_t now = millis();
  updateRadioChannel(now, connected);
  updateLeader(now);

  if ((_socketReady || _radio.ready()) && elapsed(millis(), _lastHello, HEARTBEAT_MS)) {
    heartbeat();
    _lastHello = millis();
  }
  if (_socketReady || _radio.ready()) synchronize();
  servicePreparation();
  serviceTransfers();
  serviceAutomaticUpdates();
}

